/** Status-bearing error the caller funnels through fromException() (D-11 envelope). */
function statusError(status, message) {
  const err = new Error(message);
  err.status = status;
  err.statusCode = status;
  return err;
}

/** body-parser 1.20.3: a json body must start with `{` or `[` (option strict, the default). */
const FIRST_CHAR_REGEXP = /^[\x20\x09\x0a\x0d]*([^\x20\x09\x0a\x0d])/;
const JSON_SYNTAX_CHAR = '#';
const JSON_SYNTAX_REGEXP = /#+/g;

/**
 * The strict-violation error body-parser builds for a body that is valid JSON but not an
 * object/array: it masks the body with '#' and lets the engine produce a native syntax
 * error, then puts the original text back into the message. Same 400 + `{error, stack}`
 * envelope as a parse failure.
 */
function strictViolation(str, char) {
  const index = str.indexOf(char);
  let partial = '';
  if (index !== -1) {
    partial = str.substring(0, index) + JSON_SYNTAX_CHAR;
    for (let i = index + 1; i < str.length; i += 1) {
      partial += JSON_SYNTAX_CHAR;
    }
  }
  let err;
  try {
    JSON.parse(partial);
    err = new SyntaxError('strict violation');
  } catch (engineErr) {
    engineErr.message = engineErr.message.replace(JSON_SYNTAX_REGEXP, (placeholder) =>
      str.substring(index, index + placeholder.length));
    err = engineErr;
  }
  err.status = 400;
  err.statusCode = 400;
  return err;
}

